Read the current category from INPUTS!A14 and the expense labels in A15 and A16. Build a two-criteria lookup from Sheet2 using category and expense, then map the year headers in C3:G3 to Sheet2's C1:G1. Write the resulting five-year values for Advertising and Electricity into INPUTS!C15:G16 as plain numbers.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["INPUTS"]
vws = vals["INPUTS"]
s2 = vals["Sheet2"]

def norm(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return str(x).lower()
    if isinstance(x, (int, float)):
        try:
            if float(x).is_integer():
                return str(int(x))
        except (TypeError, ValueError):
            pass
        return str(x)
    return str(x).strip().lower()

category = norm(vws["A14"].value)

lookup = {}
for r in range(3, 21):
    cat = norm(s2.cell(row=r, column=1).value)
    exp = norm(s2.cell(row=r, column=2).value)
    if cat is None and exp is None:
        continue
    lookup[(cat, exp)] = [s2.cell(row=r, column=c).value for c in range(3, 8)]

s2_headers = [norm(s2.cell(row=1, column=c).value) for c in range(3, 8)]
s2_idx = {}
for i, h in enumerate(s2_headers):
    if h is not None:
        s2_idx[h] = i

for r in (15, 16):
    exp = norm(vws.cell(row=r, column=1).value)
    row_vals = lookup.get((category, exp))
    out_vals = []

    for c in range(3, 8):
        h = norm(vws.cell(row=3, column=c).value)
        idx = s2_idx.get(h, c - 3)

        val = None
        if row_vals is not None and 0 <= idx < len(row_vals):
            val = row_vals[idx]

        if val is None:
            val = 0

        if isinstance(val, str):
            s = val.strip()
            try:
                num = float(s)
                val = int(num) if num.is_integer() else num
            except ValueError:
                val = s

        ws.cell(row=r, column=c).value = val
        out_vals.append(val)

    print(f"row {r}: {out_vals}")

wb.save(OUT)
